contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test that withdraw either reverts leaving the contract balance unchanged,
    // or succeeds and decreases address(c).balance by exactly amount.
    function run(uint256 amount) public payable {
        // Observe contract balance before attempt
        uint256 beforeBalance = address(c).balance;

        // Attempt withdraw and record whether it reverted
        bool didRevert;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        uint256 afterBalance = address(c).balance;

        // General rule:
        // If it reverted, balance is unchanged. If it succeeded, balance decreased by exactly amount.
        assert(
            (didRevert && afterBalance == beforeBalance)
            || (!didRevert && beforeBalance >= afterBalance && (beforeBalance - afterBalance) == amount)
        );
    }

    receive() external payable {}
}

