pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 amount) internal {
        uint256 beforeBalance = address(c).balance;
        bool didRevert;
        try c.withdraw(amount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 afterBalance = address(c).balance;
        assertTrue((didRevert && afterBalance == beforeBalance)
            || (!didRevert && beforeBalance >= afterBalance && (beforeBalance - afterBalance) == amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
